import {trainerSrc,playerStats,normalizePlayer} from './player-profile.mjs';
export class Social{
 constructor(g){this.g=g;this.data={friends:[],requests:[]};this.results=[];this.status='';this.loading=false;this.ready=false;this.pendingProfile=localStorage.getItem('pokeworld-profile-pending')==='1';this.timer=setInterval(()=>{if(g.page==='friends'&&!document.hidden&&!this.loading)this.refresh()},20000)}
 async api(path,body){const r=await fetch('/api/social/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let d;try{d=await r.json()}catch{throw Error('Le carnet en ligne est indisponible. Réessaie dans un instant.')}if(!r.ok)throw Error(d.error||'Le carnet n’a pas pu être actualisé.');return d}
 payload(update=false){return{...this.g.state.player,stats:playerStats(this.g.state),update}}
 paint(){if(this.g.page==='friends'&&!this.g.mode){this.query=document.querySelector('#friend-search')?.value??this.query;this.g.render()}}
 async open(){if(this.loading)return;this.loading=true;this.status='Connexion au carnet…';try{if(!this.ready){const {profile}=await this.api('profile',this.payload(this.pendingProfile));this.pendingProfile=false;localStorage.removeItem('pokeworld-profile-pending');this.ready=true;this.data.profile=profile;this.g.state.player=normalizePlayer(profile);this.g.save()}await this.fetchState();this.status='Carnet synchronisé'}catch(e){this.status=e.message}finally{this.loading=false;this.paint()}}
 async fetchState(){this.data=await this.api('state')}
 async refresh(){if(!this.ready)return this.open();this.loading=true;try{await this.fetchState();this.status='Carnet synchronisé'}catch(e){this.status=e.message}finally{this.loading=false;this.paint()}}
 async saveProfile(){try{const {profile}=await this.api('profile',this.payload(true));this.ready=true;this.pendingProfile=false;localStorage.removeItem('pokeworld-profile-pending');this.data.profile=profile;this.status='Carte synchronisée';if(this.g.page==='profile'&&!this.g.profileEditing)this.g.render()}catch(e){this.pendingProfile=true;localStorage.setItem('pokeworld-profile-pending','1');this.status=e.message;this.g.toast('Carte enregistrée sur cet appareil. '+e.message)}}
 async act(act,d){if(this.busy)return;this.busy=true;try{
  if(act==='social-refresh'){await this.open();return}
  if(!this.ready){await this.open();if(!this.ready)return}
  if(act==='friend-search'){this.query=document.querySelector('#friend-search').value.trim();if(this.query.length<2){this.g.toast('Saisis au moins deux caractères du nom de dresseur.');return}const r=await this.api('search?q='+encodeURIComponent(this.query));this.results=r.players;this.searched=true}
  if(act==='friend-add'){await this.api('request',{target:d.id});this.g.toast('Demande d’ami envoyée.');await this.fetchState()}
  if(act==='friend-respond'){const r=await this.api('respond',{id:d.id,accept:d.accept==='true'});await this.fetchState();if(r.room){this.g.net.join(r.room);this.g.toast('Invitation acceptée. Connexion au raid…')}}
  if(act==='friend-remove'){await this.api('remove',{target:d.id});await this.fetchState();this.g.toast('Ami retiré du carnet.')}
  if(act==='friend-invite'){
   let room=this.g.net.peer?.id;
   if(!room||this.g.net.guest){
    this.g.net.create();if(!this.g.net.peer)throw Error('Le service de salons est indisponible.');
    room=await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('Le salon n’a pas pu être ouvert. Réessaie.')),15000);this.g.net.peer.on('open',id=>{clearTimeout(timer);resolve(id)});this.g.net.peer.on('error',()=>{clearTimeout(timer);reject(Error('Le salon n’a pas pu être ouvert.'))})});
   }
   await this.api('request',{target:d.id,kind:'raid',room});await this.fetchState();this.g.toast('Invitation au raid envoyée.');
  }

  this.status='Carnet synchronisé';this.paint();
 }catch(e){this.status=e.message;this.g.toast(e.message);this.paint()}finally{this.busy=false}}
}
export function friendsPage(g){const s=g.social,e=g.escape.bind(g),requests=s.data.requests||[],incoming=requests.filter(r=>r.incoming),outgoing=requests.filter(r=>!r.incoming),friends=s.data.friends||[];const avatar=p=>`<img src="${trainerSrc(p.avatar)}" alt=""><div><b>${e(p.name)}</b><small>${e(p.handle||'')}</small></div>`;return g.heading('LES RENCONTRES DE POKÉWORLD','Mes amis','Retrouve tes dresseurs favoris et invite-les à partager un raid.')+`<section class="social-toolbar panel"><div><span class="eyebrow">TON CARNET DE DRESSEURS</span><strong>${friends.length} ami${friends.length>1?'s':''} · ${incoming.length} demande${incoming.length>1?'s':''}</strong><p role="status">${e(s.status||'Ouvre ton carnet pour retrouver tes amis.')}</p></div><button data-act="social-refresh">Actualiser ↻</button></section><section class="friend-search-panel panel"><h2>Retrouver un dresseur</h2><p>Recherche son nom de dresseur, ou son identifiant complet s’il y a des homonymes.</p><div class="friend-search-row"><input id="friend-search" value="${e(s.query||'')}" placeholder="Nom de dresseur…" aria-label="Nom de dresseur à rechercher" maxlength="50"><button class="primary" data-act="friend-search">Rechercher →</button></div>${s.searched?`<div class="friend-search-results">${s.results.map(p=>`<article class="social-person">${avatar(p)}<button data-act="friend-add" data-id="${e(p.id)}" ${friends.some(f=>f.id===p.id)?'disabled':''}>${friends.some(f=>f.id===p.id)?'Déjà ami':'Demander en ami'}</button></article>`).join('')||'<p>Aucun dresseur trouvé. Il doit avoir ouvert son carnet au moins une fois.</p>'}</div>`:''}</section><div class="social-columns"><section class="panel"><div class="section-title"><h2>Mes amis</h2><span>${friends.length}</span></div><div class="friend-list">${friends.map(p=>`<article class="social-person">${avatar(p)}<div class="social-person-actions"><button class="primary" data-act="friend-invite" data-id="${e(p.id)}">Inviter au raid</button><button data-act="friend-remove" data-id="${e(p.id)}" aria-label="Retirer ${e(p.name)} de mes amis">Retirer</button></div></article>`).join('')||'<div class="social-empty"><span>♧</span><h3>Une aventure à partager</h3><p>Ajoute un dresseur pour le retrouver ici après son acceptation.</p></div>'}</div></section><section class="panel"><h2>Demandes et invitations</h2><div class="social-requests">${incoming.map(p=>`<article class="social-person">${avatar(p)}<p>${p.kind==='raid'?'t’invite dans son raid':'souhaite devenir ton ami'}</p><div class="social-person-actions"><button class="primary" data-act="friend-respond" data-id="${e(p.id)}" data-accept="true">${p.kind==='raid'?'Rejoindre':'Accepter'}</button><button data-act="friend-respond" data-id="${e(p.id)}" data-accept="false">Refuser</button></div></article>`).join('')||'<p>Aucune demande reçue pour le moment.</p>'}</div>${outgoing.length?`<h3>En attente de réponse</h3>${outgoing.map(p=>`<article class="social-person outgoing">${avatar(p)}<small>${p.kind==='raid'?'Invitation au raid':'Demande d’ami'} envoyée</small></article>`).join('')}`:''}<p class="social-access-note">Le site doit être accessible aux deux dresseurs. Pour un raid, l’hôte garde son salon ouvert.</p></section></div>`}
